#[test]
fn civil_roundtrip_covers_leap_years() {
    let start = days_from_civil(2024, 1, 1);
    let end = days_from_civil(2048, 1, 1);
    for z in start..end {
        let (y, m, d) = civil_from_days(z);
        assert_eq!(days_from_civil(y, m, d), z, "roundtrip failed at {y}-{m:02}-{d:02}");
    }
}

#[test]
fn known_civil_dates() {
    assert_eq!(days_from_civil(1970, 1, 1), 0);
    assert_eq!(civil_from_days(0), (1970, 1, 1));
    assert_eq!(civil_from_days(days_from_civil(2028, 2, 29)), (2028, 2, 29));
    assert_eq!(days_from_civil(2028, 3, 1) - days_from_civil(2028, 2, 28), 2);
    // 2100 is not a leap year.
    assert_eq!(days_from_civil(2100, 3, 1) - days_from_civil(2100, 2, 28), 1);
}

#[test]
fn weekdays_and_nth_weekday() {
    assert_eq!(weekday_from_days(0), 4); // 1970-01-01 was a Thursday
    assert_eq!(weekday_from_days(days_from_civil(2026, 9, 28)), 1); // Monday
    assert_eq!(nth_weekday(2026, 1, 1, 3), 19); // third Monday of Jan 2026
    assert_eq!(nth_weekday(2026, 11, 4, 4), 26); // fourth Thursday of Nov 2026
    assert_eq!(last_weekday(2026, 5, 1), 25); // last Monday of May 2026
    assert_eq!(last_weekday(2026, 3, 0), 29); // last Sunday of March 2026
}

#[test]
fn us_dst_transitions_are_exact() {
    let s = nyse_schedule();
    // (dst start, dst end) in UTC, verified against tzdata.
    for (year, start, end) in [
        (2026, 1_772_953_200i64, 1_793_512_800i64),
        (2027, 1_805_007_600, 1_825_567_200),
        (2028, 1_836_457_200, 1_857_016_800),
    ] {
        assert!(!s.is_dst(start - 1), "{year}: DST began early");
        assert!(s.is_dst(start), "{year}: DST did not begin on time");
        assert!(s.is_dst(end - 1), "{year}: DST ended early");
        assert!(!s.is_dst(end), "{year}: DST did not end on time");
    }
}

#[test]
fn eu_dst_transitions_are_exact() {
    let s = Schedule {
        mint: Pubkey::default(),
        tz_offset_minutes: 0,
        dst_rule: DST_EU,
        base_day: 0,
        windows: vec![Window { days_mask: 0b0111110, open_minute: 480, close_minute: 990 }],
        holidays: vec![],
        early_closes: vec![],
        events: vec![],
    };
    // Last Sunday in March / October at 01:00 UTC.
    for (year, m_start, d_start, m_end, d_end) in
        [(2026u32 as i32, 3u32, 29u32, 10u32, 25u32), (2027, 3, 28, 10, 31)]
    {
        let start = days_from_civil(year, m_start, d_start) * 86_400 + 3_600;
        let end = days_from_civil(year, m_end, d_end) * 86_400 + 3_600;
        assert!(!s.is_dst(start - 1), "{year}: EU DST began early");
        assert!(s.is_dst(start), "{year}: EU DST did not begin");
        assert!(s.is_dst(end - 1), "{year}: EU DST ended early");
        assert!(!s.is_dst(end), "{year}: EU DST did not end");
    }
}

#[test]
fn a_market_with_no_dst_never_shifts() {
    let tokyo = Schedule {
        mint: Pubkey::default(),
        tz_offset_minutes: 9 * 60,
        dst_rule: DST_NONE,
        base_day: 0,
        windows: vec![Window { days_mask: 0b0111110, open_minute: 540, close_minute: 900 }],
        holidays: vec![],
        early_closes: vec![],
        events: vec![],
    };
    for ts in [1_772_953_200i64, 1_793_512_800, 1_805_007_600] {
        assert!(!tokyo.is_dst(ts));
    }
}

#[test]
fn schedule_args_are_validated() {
    let ok = ScheduleArgs {
        tz_offset_minutes: -300,
        dst_rule: DST_US,
        base_day: 20454,
        windows: vec![Window { days_mask: 0b0111110, open_minute: 570, close_minute: 960 }],
        holidays: vec![1, 2, 3],
        early_closes: vec![],
        events: vec![],
    };
    assert!(ok.validate().is_ok());

    let no_windows = ScheduleArgs { windows: vec![], ..ok.clone() };
    assert!(no_windows.validate().is_err(), "a schedule with no windows must be rejected");

    let unsorted = ScheduleArgs { holidays: vec![5, 3, 9], ..ok.clone() };
    assert!(unsorted.validate().is_err(), "unsorted holidays break the binary search");

    let dup = ScheduleArgs { holidays: vec![3, 3], ..ok.clone() };
    assert!(dup.validate().is_err());

    let backwards = ScheduleArgs {
        windows: vec![Window { days_mask: 0b0111110, open_minute: 960, close_minute: 570 }],
        ..ok.clone()
    };
    assert!(backwards.validate().is_err());

    let bad_dst = ScheduleArgs { dst_rule: 9, ..ok.clone() };
    assert!(bad_dst.validate().is_err());

    let bad_tz = ScheduleArgs { tz_offset_minutes: 2000, ..ok };
    assert!(bad_tz.validate().is_err());
}

