#[test]
fn session_is_a_uniform_window_on_every_trading_day() {
    let s = nyse_schedule();
    let start = days_from_civil(2026, 1, 1);
    let end = days_from_civil(2031, 1, 1);
    for z in start..end {
        let wd = weekday_from_days(z);
        let offset = (z - s.base_day as i64) as u16;
        if wd == 0 || wd == 6 || s.holidays.binary_search(&offset).is_ok() {
            continue;
        }
        let dst = s.is_dst(z * 86_400 + 12 * 3_600);
        let base = z * 86_400 + (if dst { 4 } else { 5 }) * 3_600;
        let at = |min: i64| base + min * 60;
        let (y, m, d) = civil_from_days(z);
        assert_eq!(s.state_at(at(9 * 60 + 29)), MarketState::Closed, "{y}-{m:02}-{d:02} 09:29");
        assert_eq!(s.state_at(at(9 * 60 + 30)), MarketState::Open, "{y}-{m:02}-{d:02} 09:30");
        assert_eq!(s.state_at(at(15 * 60 + 59)), MarketState::Open, "{y}-{m:02}-{d:02} 15:59");
        assert_eq!(s.state_at(at(16 * 60)), MarketState::Closed, "{y}-{m:02}-{d:02} 16:00");
    }
}

#[test]
fn early_close_shortens_the_day() {
    let mut s = nyse_schedule();
    // 2026-11-27, the Friday after Thanksgiving.
    let day = days_from_civil(2026, 11, 27);
    let offset = (day - s.base_day as i64) as u16;
    s.early_closes = vec![EarlyClose { day_offset: offset, close_minute: 780 }]; // 13:00
    let base = day * 86_400 + 5 * 3_600; // EST in November
    assert_eq!(s.state_at(base + (12 * 60 + 59) * 60), MarketState::Open);
    assert_eq!(s.state_at(base + 13 * 3_600), MarketState::Closed);
}

#[test]
fn holidays_outside_the_horizon_do_not_block() {
    // Past the generated horizon the schedule simply has no holiday data, so a
    // weekday there trades. This is the documented limit of a data-driven
    // calendar; the horizon is chosen to be long.
    let s = nyse_schedule();
    let last = s.base_day as i64 + *s.holidays.last().unwrap() as i64;
    let (y, _, _) = civil_from_days(last);
    assert!(y >= 2046, "holiday horizon should reach at least 2046, got {y}");
}

#[test]
fn events_override_the_weekly_windows() {
    let mut s = nyse_schedule();
    // Mon 2026-09-28, 11:00 ET -- normally open.
    let midsession = 1_790_607_600i64;
    // Sat 2026-10-03, 11:00 ET -- normally closed.
    let weekend = 1_791_039_600i64;
    assert_eq!(s.state_at(midsession), MarketState::Open);
    assert_eq!(s.state_at(weekend), MarketState::Closed);

    // A deny event shuts an otherwise-open session.
    s.events = vec![Event { start: midsession - 600, end: midsession + 600, allow: false }];
    assert_eq!(s.state_at(midsession), MarketState::Closed);
    assert_eq!(s.state_at(midsession + 1_200), MarketState::Open, "outside the event, normal rules");

    // An allow event opens an otherwise-closed weekend.
    s.events = vec![Event { start: weekend - 600, end: weekend + 600, allow: true }];
    assert_eq!(s.state_at(weekend), MarketState::Open);
    assert_eq!(s.state_at(weekend + 1_200), MarketState::Closed);
}

#[test]
fn a_deny_event_beats_an_overlapping_allow() {
    let mut s = nyse_schedule();
    let t = 1_791_039_600i64; // Saturday
    s.events = vec![
        Event { start: t - 600, end: t + 600, allow: true },
        Event { start: t - 300, end: t + 300, allow: false },
    ];
    assert_eq!(s.state_at(t), MarketState::Closed, "deny must win");
    assert_eq!(s.state_at(t + 450), MarketState::Open, "only the allow covers this instant");
}

#[test]
fn an_allow_event_also_overrides_a_holiday() {
    let mut s = nyse_schedule();
    let christmas = 1_798_214_400i64; // 2026-12-25 11:00 ET
    assert_eq!(s.state_at(christmas), MarketState::Holiday);
    s.events = vec![Event { start: christmas - 60, end: christmas + 60, allow: true }];
    assert_eq!(s.state_at(christmas), MarketState::Open);
}

#[test]
fn malformed_events_are_rejected() {
    let base = ScheduleArgs {
        tz_offset_minutes: -300,
        dst_rule: DST_US,
        base_day: 20454,
        windows: vec![Window { days_mask: 0b0111110, open_minute: 570, close_minute: 960 }],
        holidays: vec![],
        early_closes: vec![],
        events: vec![],
    };
    assert!(base.validate().is_ok());

    let backwards = ScheduleArgs {
        events: vec![Event { start: 100, end: 100, allow: true }],
        ..base.clone()
    };
    assert!(backwards.validate().is_err(), "a zero-length event must be rejected");

    let too_many = ScheduleArgs {
        events: (0..MAX_EVENTS as i64 + 1)
            .map(|i| Event { start: i * 10, end: i * 10 + 5, allow: true })
            .collect(),
        ..base
    };
    assert!(too_many.validate().is_err());
}

/// The generated holiday table must cover every year it claims to, with no
/// gaps. The 2.2M-slot differential against tzdata is run out of band (see
/// README); this guards the data the differential depends on.
#[test]
fn holiday_table_has_no_gaps_across_the_horizon() {
    let s = nyse_schedule();
    let mut per_year = std::collections::BTreeMap::new();
    for off in s.holidays.iter() {
        let (y, _, _) = civil_from_days(s.base_day as i64 + *off as i64);
        *per_year.entry(y).or_insert(0) += 1;
    }
    let first = *per_year.keys().next().unwrap();
    let last = *per_year.keys().last().unwrap();
    assert_eq!(first, 2026, "horizon should start in 2026");
    assert!(last >= 2046, "horizon should reach 2046, got {last}");
    for y in first..=last {
        let n = per_year.get(&y).copied().unwrap_or(0);
        // NYSE observes 9 or 10 full closures a year: New Year's is not
        // observed when 1 January falls on a Saturday.
        assert!(
            (9..=10).contains(&n),
            "{y} has {n} holidays, expected 9 or 10"
        );
    }
}
